CREATE OR REPLACE FUNCTION public.fn_get_material_return_inspection_by_loan_id(p_loan_id uuid)  RETURNS TABLE(id uuid, loan_id uuid, order_id uuid, material_product_id uuid, returned_quantity integer, inspected_at timestamp with time zone, inspected_by_user_id uuid, inspected_by_email character varying, condition character varying, quantity_approved_for_stock integer, quantity_requiring_cleaning integer, quantity_damaged integer, quantity_missing integer, inspection_notes text, deposit_disposition character varying, deposit_deduction_amount numeric, resolution_status character varying, created_at timestamp with time zone, product_name character varying, product_sku character varying)  LANGUAGE sql  STABLE AS $function$     SELECT          i.id, i.loan_id, i.order_id, i.material_product_id, i.returned_quantity,         i.inspected_at, i.inspected_by_user_id, i.inspected_by_email, i.condition,         i.quantity_approved_for_stock, i.quantity_requiring_cleaning,         i.quantity_damaged, i.quantity_missing, i.inspection_notes,         i.deposit_disposition, i.deposit_deduction_amount, i.resolution_status, i.created_at,         p.name AS product_name, p.sku AS product_sku     FROM material_return_inspections i     JOIN material_products p ON i.material_product_id = p.id     WHERE i.loan_id = p_loan_id     ORDER BY i.created_at DESC      LIMIT 1; $function$ ;
